namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new(1, "Classic Margherita Pizza", "Italian",
                ["2 cups flour", "1 cup warm water", "1 tsp yeast", "1 tsp salt", "1/2 cup tomato sauce", "8 oz fresh mozzarella", "Fresh basil leaves", "2 tbsp olive oil"],
                ["Mix flour, water, yeast, and salt to form dough. Knead 10 minutes.", "Let dough rise for 1 hour.", "Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread tomato sauce, add sliced mozzarella.", "Bake for 12-15 minutes until crust is golden.", "Top with fresh basil and drizzle with olive oil."],
                "A timeless Italian classic with fresh mozzarella and basil."),

            new(2, "Chicken Tikka Masala", "Indian",
                ["1 lb chicken breast, cubed", "1 cup yogurt", "2 tbsp tikka masala paste", "1 can (14 oz) crushed tomatoes", "1 cup heavy cream", "1 onion, diced", "3 cloves garlic, minced", "1 tbsp ginger, grated", "2 tbsp butter", "Rice for serving"],
                ["Marinate chicken in yogurt and tikka paste for 1 hour.", "Sauté onion, garlic, and ginger in butter until soft.", "Add marinated chicken and cook until browned.", "Pour in crushed tomatoes and simmer 15 minutes.", "Stir in heavy cream and simmer 10 more minutes.", "Season with salt to taste. Serve over steamed rice."],
                "Creamy, aromatic curry that's become a worldwide favorite."),

            new(3, "Beef Tacos", "Mexican",
                ["1 lb ground beef", "1 packet taco seasoning", "8 small tortillas", "1 cup shredded lettuce", "1 cup diced tomatoes", "1/2 cup shredded cheddar", "1/4 cup sour cream", "Salsa to taste"],
                ["Brown ground beef in a skillet over medium-high heat.", "Drain excess fat and add taco seasoning with 1/4 cup water.", "Simmer for 5 minutes until sauce thickens.", "Warm tortillas in a dry skillet or microwave.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomatoes, cheese, sour cream, and salsa."],
                "Quick, customizable, and always a crowd-pleaser."),

            new(4, "Pad Thai", "Asian",
                ["8 oz rice noodles", "2 tbsp tamarind paste", "2 tbsp fish sauce", "1 tbsp sugar", "2 eggs", "1 cup bean sprouts", "1/4 cup crushed peanuts", "2 green onions, sliced", "1 lime", "2 tbsp vegetable oil", "8 oz shrimp (optional)"],
                ["Soak rice noodles in warm water for 30 minutes, then drain.", "Mix tamarind paste, fish sauce, and sugar for the sauce.", "Heat oil in a wok over high heat. Cook shrimp if using.", "Push to side, scramble eggs in the wok.", "Add noodles and sauce, toss to coat evenly.", "Add bean sprouts and green onions, stir-fry 1 minute.", "Serve with crushed peanuts and lime wedges."],
                "Sweet, sour, and savory Thai street food at home."),

            new(5, "Caesar Salad", "American",
                ["1 head romaine lettuce", "1/2 cup Caesar dressing", "1/4 cup grated Parmesan", "1 cup croutons", "2 anchovy fillets (optional)", "1 lemon", "Black pepper to taste"],
                ["Wash and chop romaine lettuce into bite-sized pieces.", "If using anchovies, mince and mix into the dressing.", "Toss lettuce with Caesar dressing until evenly coated.", "Add croutons and toss gently.", "Top with grated Parmesan and a squeeze of lemon.", "Finish with freshly cracked black pepper."],
                "A crisp, tangy salad perfect as a side or light meal."),

            new(6, "Spaghetti Carbonara", "Italian",
                ["1 lb spaghetti", "6 oz pancetta or guanciale", "4 egg yolks", "1 cup grated Pecorino Romano", "Black pepper to taste", "Salt for pasta water"],
                ["Cook spaghetti in salted boiling water until al dente.", "While pasta cooks, crisp pancetta in a skillet.", "Whisk egg yolks with Pecorino and plenty of black pepper.", "Reserve 1 cup pasta water, then drain spaghetti.", "Toss hot pasta with pancetta (off heat).", "Quickly stir in egg mixture, adding pasta water to create a creamy sauce.", "Serve immediately with extra Pecorino."],
                "Rich, silky Roman pasta — no cream needed."),

            new(7, "Guacamole", "Mexican",
                ["3 ripe avocados", "1 lime, juiced", "1/2 tsp salt", "1/2 cup diced onion", "1 jalapeño, seeded and minced", "2 tbsp fresh cilantro, chopped", "1 diced tomato"],
                ["Cut avocados in half, remove pit, scoop into a bowl.", "Mash with a fork to desired consistency.", "Stir in lime juice and salt.", "Mix in onion, jalapeño, cilantro, and tomato.", "Taste and adjust seasoning.", "Serve immediately with tortilla chips."],
                "Fresh, zesty dip ready in 10 minutes."),

            new(8, "Miso Soup", "Asian",
                ["4 cups dashi stock", "3 tbsp white miso paste", "1/2 block soft tofu, cubed", "2 green onions, sliced", "1 sheet nori, cut into strips", "1 tbsp wakame seaweed (dried)"],
                ["Heat dashi stock in a saucepan until simmering.", "Rehydrate wakame in warm water for 5 minutes, drain.", "Remove a ladle of hot stock and dissolve miso paste into it.", "Add dissolved miso back to the pot (do not boil).", "Add tofu cubes and wakame.", "Serve in bowls topped with green onions and nori strips."],
                "A comforting Japanese staple, light yet satisfying."),

            new(9, "Butter Chicken", "Indian",
                ["1 lb chicken thighs, cubed", "1 cup tomato puree", "1/2 cup heavy cream", "3 tbsp butter", "1 onion, diced", "2 cloves garlic, minced", "1 tbsp garam masala", "1 tsp turmeric", "1 tsp chili powder", "Salt to taste", "Rice or naan for serving"],
                ["Season chicken with garam masala, turmeric, chili powder, and salt.", "Melt butter and sear chicken until golden. Remove and set aside.", "Sauté onion and garlic in the same pan until softened.", "Add tomato puree and simmer 10 minutes.", "Return chicken to the pan, simmer 15 minutes.", "Stir in heavy cream and cook 5 more minutes.", "Serve with basmati rice or warm naan."],
                "Velvety, mildly spiced — the ultimate comfort curry."),

            new(10, "Chocolate Chip Cookies", "American",
                ["2 1/4 cups flour", "1 tsp baking soda", "1 tsp salt", "1 cup butter, softened", "3/4 cup sugar", "3/4 cup brown sugar", "2 eggs", "2 tsp vanilla extract", "2 cups chocolate chips"],
                ["Preheat oven to 375°F (190°C).", "Mix flour, baking soda, and salt in a bowl.", "Beat butter and both sugars until creamy.", "Add eggs and vanilla to butter mixture, beat well.", "Gradually blend in flour mixture.", "Fold in chocolate chips.", "Drop rounded tablespoons onto ungreased baking sheets.", "Bake 9-11 minutes until golden brown.", "Cool on baking sheet for 2 minutes, then transfer to wire rack."],
                "Crispy edges, chewy center — the gold standard cookie.")
        };
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public IReadOnlyList<Recipe> GetAllRecipes()
    {
        return _recipes.AsReadOnly();
    }

    public void AddRecipe(string title, string category, List<string> ingredients, List<string> steps)
    {
        var id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe(id, title, category, ingredients, steps, "A community-submitted recipe."));
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();
        _ratings[recipeId].Add(stars);
    }

    public (double Average, int Count) GetRating(int recipeId)
    {
        if (!_ratings.TryGetValue(recipeId, out var ratings) || ratings.Count == 0)
            return (0, 0);
        return (ratings.Average(), ratings.Count);
    }
}

public record Recipe(
    int Id,
    string Title,
    string Category,
    IReadOnlyList<string> Ingredients,
    IReadOnlyList<string> Steps,
    string Description);

@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center gap-2">
    <div class="stars" role="group" aria-label="Rate this recipe">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                    class="btn btn-link p-0 fs-4 text-decoration-none @(star <= _selectedRating ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    aria-label="@star stars">
                @(star <= _selectedRating ? "★" : "☆")
            </button>
        }
    </div>

    @if (_ratingCount > 0)
    {
        <span class="text-muted small">
            @_averageRating.ToString("F1") avg (@_ratingCount @(_ratingCount == 1 ? "rating" : "ratings"))
        </span>
    }
    else
    {
        <span class="text-muted small">No ratings yet</span>
    }

    @if (_justRated)
    {
        <span class="text-success small">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Inject]
    private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private double _averageRating;
    private int _ratingCount;
    private bool _justRated;

    protected override void OnParametersSet()
    {
        LoadRating();
    }

    private void SubmitRating(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _justRated = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var (avg, count) = RecipeService.GetRating(RecipeId);
        _averageRating = avg;
        _ratingCount = count;
    }
}

