@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center gap-2">
    <div class="stars" role="group" aria-label="Rate this recipe">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                    class="btn btn-link p-0 fs-4 text-decoration-none @(star <= _selectedRating ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    aria-label="@star stars">
                @(star <= _selectedRating ? "★" : "☆")
            </button>
        }
    </div>

    @if (_ratingCount > 0)
    {
        <span class="text-muted small">
            @_averageRating.ToString("F1") avg (@_ratingCount @(_ratingCount == 1 ? "rating" : "ratings"))
        </span>
    }
    else
    {
        <span class="text-muted small">No ratings yet</span>
    }

    @if (_justRated)
    {
        <span class="text-success small">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Inject]
    private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private double _averageRating;
    private int _ratingCount;
    private bool _justRated;

    protected override void OnParametersSet()
    {
        LoadRating();
    }

    private void SubmitRating(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _justRated = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var (avg, count) = RecipeService.GetRating(RecipeId);
        _averageRating = avg;
        _ratingCount = count;
    }
}

